ALTER TABLE GW_BINDING MODIFY (binding_key_hash NULL);

CREATE OR REPLACE TRIGGER trg_gw_binding_key_hash_compat
BEFORE INSERT OR UPDATE OF environment_code, host_pattern, path_pattern, http_method, api_version, route_version
ON GW_BINDING
FOR EACH ROW
BEGIN
    :NEW.binding_key_hash := LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(
        LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(NVL(NULLIF(TRIM(:NEW.environment_code), ''), 'DEFAULT'), 'AL32UTF8'), 'SHA256'))) ||
        LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(NVL(NULLIF(TRIM(:NEW.host_pattern), ''), '*'), 'AL32UTF8'), 'SHA256'))) ||
        LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(TRIM(:NEW.path_pattern), 'AL32UTF8'), 'SHA256'))) ||
        LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(NVL(NULLIF(TRIM(:NEW.http_method), ''), '*'), 'AL32UTF8'), 'SHA256'))) ||
        LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(NVL(NULLIF(TRIM(:NEW.api_version), ''), 'v1'), 'AL32UTF8'), 'SHA256'))) ||
        LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(NVL(NULLIF(TRIM(:NEW.route_version), ''), '1'), 'AL32UTF8'), 'SHA256'))),
        'AL32UTF8'), 'SHA256')));
END;
/

ALTER TABLE CMN_RESPONSE_CODE MODIFY (http_status NULL);
